        subject.trim()||(convert?'[DÁN ĐỀ BÀI Ở ĐÂY]':complete?'[DÁN BẢN NHÁP CÒN THIẾU Ở ĐÂY]':'[GHI Ý TƯỞNG NGẮN Ở ĐÂY]')
