    function printHTML(html){const frame=document.createElement('iframe');frame.className='print-frame';frame.setAttribute('aria-hidden','true');frame.style.cssText='position:fixed;width:0;height:0;border:0;right:0;bottom:0';frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),60000)};frame.srcdoc=html;document.body.append(frame)}
    // Standards comparison: the same case read under each chart model, side by side; findings not shared by every model are marked.
