    async function importSession(e){const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw new Error('Tệp vượt giới hạn 2 MB.');const parsed=parseCases(await file.text());if(parsed.length!==1)throw new Error('Chọn tệp chứa đúng một hồ sơ theo dõi.');saveHistory();clinical.value=parsed[0];quickDrafts.value={};lastSaved.value=JSON.stringify(parsed[0]);selectedTime.value=parsed[0].observations[0].time;clinicalError.value='';notify('Đã mở phiên theo dõi từ JSON')}catch(error){clinicalError.value=error.message}finally{e.target.value=''}}
