    function applyImported(notation,context={}){if(context.branch&&context.destination==='clinical'){applyClinicalBranch(notation,context);return}if(context.updateCurrent){applyAIUpdate(notation,context);return}if(context.destination==='clinical'){if(!allowCaseSwitch()||pendingQuickTimes.value.length){aiReplyError.value='Ghi nhận hoặc Hủy bản nhập dở trước khi mở hồ sơ từ AI.';return}try{const parsed=parseCases(aiReply.value,notation),target=parsed[Number(context.selected)||0];if(!target)throw new Error('Chọn một ca hợp lệ để theo dõi.');saveHistory();history.value.at(-1).selectedTime=selectedTime.value;clinical.value=clone(target);quickDrafts.value={};selectedTime.value=target.observations[0].time;if(parsed.review){if(parsed.review.standard)standard.value=parsed.review.standard;if(parsed.review.design){design.value=designOptions(parsed.review.design);mono.value=parsed.review.mono;compact.value=parsed.review.compact}}mode.value='clinical';aiSession.value={...aiSession.value,refinementBase:null,refinementScope:'content',branchMode:false};importerOpen.value=false;toolTab.value='overview';focusMode.value=false;clinicalError.value='';aiReplyError.value='';notify('Đã mở ca đang xem trước trong Theo dõi. Có thể hoàn tác.','success')}catch(e){aiReplyError.value=e.message}return}if(!allowCaseSwitch()){aiReplyError.value='Áp dụng hoặc Hủy bản nháp của ca hiện tại trước khi nhập ca mới.';return}let imported;try{imported=applyParsedCases(parseCases(aiReply.value,notation),context.selectedOnly?Number(context.selected)||0:null,context.append===true);aiReplyError.value=''}catch(e){aiReplyError.value=e.message;return}mode.value='exam';aiSession.value={...aiSession.value,refinementBase:null,refinementScope:'content',branchMode:false};importerOpen.value=false;toolTab.value='overview';focusMode.value=false;notify(imported?.review?'Đã mở bản kiểm tra: '+cases.value.length+' ca · '+STANDARD_NAMES[standard.value]+', đúng thiết kế của người gửi.':(context.append?'Đã thêm '+imported.length+' ca; giữ các ca đã có.':'Đã vẽ '+cases.value.length+' sản đồ từ JSON.')+' Chạm vào điểm để chỉnh tiếp.','success')}
