    async function exportCase(c,type){if(type==='json'){downloadReview();return}if(exporting.value)return;if(!await settlePoint()||exporting.value)return;c=c.id===activeCase.value.id?activeCase.value:c;if(c!==clinical.value&&draftDirty.value){notify('Áp dụng hoặc Hủy bản nháp trước khi xuất.','error');return}if(c===clinical.value&&!requireQuickCommit())return;const context=actionContext.value;exporting.value=c.id+type;setFeedback('export','busy','Đang dựng '+type.toUpperCase()+'…',context);try{const checked=validateCase(c),options=clone(chartOptions.value),pdfOptions=clone(outputSettings.value);const name=(outputName.value.trim()||'san-do-'+c.id+(compact.value?'-rut-gon':'')+(mono.value?'-don-sac':'')).replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').slice(0,120);let blob;if(type==='svg')blob=new Blob([svgDocument(buildSVG(checked,options,true))],{type:'image/svg+xml;charset=utf-8'});else{const canvas=await rasterize(checked,options);blob=type==='pdf'?createPDF(canvas,pdfOptions):png300(canvas.toDataURL('image/png'))}download(blob,name+'.'+type);setFeedback('export','success','Đã xuất '+type.toUpperCase(),context);exportedCases.value={...exportedCases.value,[c.id]:true};notify('Đã tạo '+(type==='png'?'PNG 300 DPI':type.toUpperCase())+' để tải xuống.','success')}catch(e){setFeedback('export','error','Thử xuất lại',context);notify('Không thể xuất: '+e.message,'error')}finally{exporting.value=''}}
    const nextExam=computed(()=>{const c=clinical.value;const last=[...c.observations].sort((a,b)=>a.time-b.time).filter(o=>o.cervix!==null).at(-1);if(!last)return {label:'Chưa ghi nhận lần khám CTC',detail:'Ghi nhận độ mở để tính thời điểm đánh giá kế tiếp.',overdue:false};if(last.cervix>=10)return {label:'Chuyển theo dõi giai đoạn II',detail:'Không áp dụng nhắc khám CTC định kỳ 4 giờ khi đã mở trọn.',overdue:false};const interval=clamp(Number(examInterval.value)||4,.5,4),next=last.time+interval;const end=new Date(c.patient.date+'T'+c.patient.startTime+':00').getTime()+next*3600000;const overdue=Number.isFinite(end)&&now.value>=end,minutes=Number.isFinite(end)?Math.round(Math.abs(end-now.value)/60000):Infinity,span=minutes<60?minutes+' phút':Math.floor(minutes/60)+' giờ'+(minutes%60?' '+minutes%60+' phút':'');return {countdown:minutes<=1440?(overdue?'quá '+span:'còn '+span):'',label:'Đánh giá kế tiếp: '+clockAt(c,next),detail:'Sau '+interval+' giờ từ lần khám CTC '+clockAt(c,last.time)+'.'+(overdue?' Đã đến hoặc quá thời điểm dự kiến.':'')+' Có dấu hiệu bất thường: đánh giá sớm hơn. ['+(standard.value==='lcg'?'WHO LCG':'UMP 2020')+']',overdue}});
