    async function executeCommand(item){if(item.disabled)return;commandOpen.value=false;await Vue.nextTick();item.run()}
    function studioKey(event){
      if(event.defaultPrevented)return;
      if(learningOpen.value||homeOpen.value||studio.panel||importerOpen.value)return;
      const mod=event.ctrlKey||event.metaKey,key=event.key.toLowerCase(),typing=event.target.closest('input,textarea,select,[contenteditable="true"]');
      if(mod&&key==='k'){event.preventDefault();preferencesOpen.value=false;if(commandOpen.value)commandOpen.value=false;else openCommands();return}
      if(mod&&key==='s'&&!event.shiftKey&&!event.altKey){event.preventDefault();quickSave();return}
      if(commandOpen.value||preferencesOpen.value||importerOpen.value||shortcutsOpen.value)return;
      if(event.key==='Escape'&&inlineEditor.value){event.preventDefault();inlineOwner.value?.closeCellEditor();return}
      if(event.key==='Escape'&&!event.target.closest('dialog')&&!sheetOpen.value){if(focusMode.value){toggleFocus();return}if((dataPoint.value||dataMode.value==='add')&&['overview','data'].includes(toolTab.value)&&dataMode.value!=='manual'){event.preventDefault();closeToolbox();return}if(toolTab.value!=='overview'){event.preventDefault();closeToolbox();return}}
      if(key==='?'&&!typing&&!mod){event.preventDefault();shortcutsOpen.value=true;return}
      if(key==='0'&&!typing&&!mod&&!event.altKey){event.preventDefault();selectTool('overview');return}
      if(mod&&key===','){event.preventDefault();openPreferences();return}
      if(sheetOpen.value){if(event.key==='Escape'){event.preventDefault();closeToolbox();return}}
      if(mod&&event.key==='Enter'){event.preventDefault();const form=event.target.closest('form');if(form&&form.checkVisibility())form.requestSubmit();else commitDraft();return}
      if(event.altKey&&!mod&&['1','2','3','4'].includes(key)){event.preventDefault();selectTool(toolTabs[Number(key)-1].id);return}
      if(typing||event.target.closest('dialog'))return;
      if(mod&&(key==='z'||key==='y')){event.preventDefault();if(event.shiftKey||key==='y')redoAny();else undoAny();return}
      if(event.altKey&&['ArrowLeft','ArrowRight'].includes(event.key)&&['overview','data'].includes(toolTab.value)&&dataPoint.value){event.preventDefault();moveDataPoint(event.key==='ArrowLeft'?-1:1);return}
      if(event.altKey&&['ArrowLeft','ArrowRight'].includes(event.key)&&mode.value==='exam'){event.preventDefault();selectMoment(clamp(selectedMoment.value+(event.key==='ArrowLeft'?-1:1),0,caseForView(activeCase.value).observations.length-1));return}
      if(key==='f'&&!mod&&!event.altKey){event.preventDefault();toggleFocus()}
      if(event.key==='Escape'&&focusMode.value)toggleFocus();
    }
    function fieldValidationMessage(field){const v=field.validity;return v.valueMissing?'Điền ô này trước khi lưu.':v.rangeUnderflow?'Giá trị tối thiểu là '+field.min+'.':v.rangeOverflow?'Giá trị tối đa là '+field.max+'.':v.stepMismatch?'Nhập theo bước '+field.step+(field.min?' từ '+field.min:'')+'.':'Kiểm tra lại giá trị trong ô này.'}
