    function clearFieldError(event){const field=event.target;if(!field.matches('input,select,textarea'))return;if(!field.validity.valid){invalidField(event);return}if(!field.dataset.nativeInvalid)return;delete field.dataset.nativeInvalid;field.removeAttribute('aria-invalid');field.closest('.field')?.removeAttribute('data-validation-message')}
    const root=document.getElementById('app');root.addEventListener('invalid',invalidField,true);root.addEventListener('input',clearFieldError);root.addEventListener('change',clearFieldError);
    onUnmounted(()=>{root.removeEventListener('invalid',invalidField,true);root.removeEventListener('input',clearFieldError);root.removeEventListener('change',clearFieldError)});
    watch(aiReply,()=>{aiReplyError.value=''});
