    watch([jsonPrompt,jsonBrief],()=>{delete feedback.value.promptCopy},{deep:true});
    const closeMenus=e=>{for(const menu of document.querySelectorAll('.workspace-menu[open],.case-menu[open],.clinical-options[open],.tool-groups[open],.rail-more[open],.ai-tool-menu[open],.ai-reply-options[open],.project-actions[open]'))if(!menu.contains(e.target))menu.open=false};
